/**
 * Archive Gallery: real photos (Wikimedia Commons, public domain / CC, credits baked on each print) for the three
 * demo stops. On those stops a small collage labelled "Archive Gallery" replaces the people hologram right of the
 * card. Pinching it explodes the collage: each photo flies out to its own framed print, splayed across the right
 * side of the view. Pinching any print folds them back into the collage.
 *
 * The art is baked by tools/render_archive_gallery.py from tools/archive-photos.json (Scripts/ArchivePhotos.ts, with
 * each print's aspect, is generated by it).
 *
 * Pure TypeScript (no Lens Studio APIs), unit-tested in tests/archive.test.ts.
 */

/** The collage cover is 16:9, like the people hologram it replaces. */
export const ARCHIVE_COVER_ASPECT = 9 / 16

export type ArchiveHit = "open" | "close" | ""

export interface ArchiveSlot {
  /** Centre, in the collage's plane (cm, +x = the wearer's right, +y = up), relative to the exploded layout's anchor. */
  x: number
  y: number
  w: number
  h: number
  /** Slight in-plane tilt (degrees), so the prints read as photographs laid out by hand. */
  tilt: number
  /** Small depth stagger toward the wearer (cm), so overlapping edges never z-fight. */
  z: number
}

const TILTS = [-3, 2, -1.5, 3, -2, 1.5]

/**
 * Exploded layout: prints of equal height `rowH` (width = aspect x height), up to `perRow` to a row, `gap` cm apart,
 * rows centred on x = 0 and stacked around y = 0, the first row on top. Returns one slot per aspect, in order.
 */
export function archiveLayout(aspects: number[], rowH: number, gap: number, perRow = 3): ArchiveSlot[] {
  const rows: number[][] = []
  for (let i = 0; i < aspects.length; i += perRow) rows.push(aspects.slice(i, i + perRow).map((_, k) => i + k))
  const totalH = rows.length * rowH + (rows.length - 1) * gap
  const out: ArchiveSlot[] = []
  rows.forEach((row, r) => {
    const widths = row.map((i) => Math.max(0.2, aspects[i]) * rowH)
    const rowW = widths.reduce((a, b) => a + b, 0) + (row.length - 1) * gap
    let x = -rowW / 2
    const y = totalH / 2 - rowH / 2 - r * (rowH + gap)
    row.forEach((i, k) => {
      out.push({x: x + widths[k] / 2, y, w: widths[k], h: rowH, tilt: TILTS[i % TILTS.length], z: 0.6 * (i % 3)})
      x += widths[k] + gap
    })
  })
  return out
}

/** Bounding half-extents of a layout (cm). */
export function archiveExtent(slots: ArchiveSlot[]): {hw: number; hh: number} {
  let hw = 0, hh = 0
  for (const s of slots) {
    hw = Math.max(hw, Math.abs(s.x) + s.w / 2)
    hh = Math.max(hh, Math.abs(s.y) + s.h / 2)
  }
  return {hw, hh}
}

/** Ease-out for the explode / fold animation (0..1). */
export function archiveEase(t: number): number {
  const c = Math.min(1, Math.max(0, t))
  return 1 - Math.pow(1 - c, 3)
}
